_PRINT_PAPER = [   # the sheet that slides out of the black printer, top row first (grey bars = printed lines, no text)
    "PPPPPPPPPPPPPPPPPp",
    "PPppppppPppppPPPPp",
    "PPPPPPPPPPPPPPPPPp",
    "PPppppPpppppppPPPp",
    "PPPPPPPPPPPPPPPPPp",
    "pppppppppppppppppp",
]
def _sheet(n):   # n rows of the sheet out of the slot: the leading (bottom) edge comes out first
    rows = _PRINT_PAPER[len(_PRINT_PAPER) - n:]
    return {(7 + x, 11 + y): ch for y, r in enumerate(rows) for x, ch in enumerate(r)}

